namespace Oluso.Core.Events;

/// <summary>
/// Provides event property definitions and data extraction from a specific assembly.
/// Implementations are auto-generated by the EventPropertyGenerator source generator.
/// Register via <c>services.AddEventPropertySource&lt;T&gt;()</c>.
/// </summary>
public interface IEventPropertySource
{
    /// <summary>
    /// Gets event property definitions keyed by event class name (e.g., "UserSignedInEvent").
    /// </summary>
    IReadOnlyDictionary<string, EventPropertyDefinition[]> GetEventProperties();

    /// <summary>
    /// Gets event property definitions keyed by webhook event type (e.g., "auth.login_success").
    /// Only includes events that define a non-null WebhookEventType.
    /// </summary>
    IReadOnlyDictionary<string, EventPropertyDefinition[]> GetPropertiesByWebhookType();

    /// <summary>
    /// Extracts event data as a flat snake_case dictionary without using reflection.
    /// Returns null if the event type is not known to this source.
    /// </summary>
    Dictionary<string, object?>? ExtractData(OlusoEvent evt);

    /// <summary>
    /// Resolves an event CLR type by class name without reflection.
    /// Returns null if the event type is not known to this source.
    /// </summary>
    Type? ResolveEventType(string eventClassName);
}
